import{c as r,Q as a,j as o,m as t}from"./chunks/framework.DGHXLY8X.js";const u=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md","lastUpdated":null}'),i={name:"changelog.md"};function l(n,e,c,d,s,h){return a(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>Generated at build time from <a href="https://github.com/smazurov/videonode/blob/main/changelog.yml" target="_blank" rel="noreferrer"><code>changelog.yml</code></a>. Cross-reference <a href="https://github.com/smazurov/videonode/releases" target="_blank" rel="noreferrer">GitHub Releases</a> for download links and signed artifacts.</p><h2 id="_4-0-0-rc6" tabindex="-1">4.0.0-rc6 <a class="header-anchor" href="#_4-0-0-rc6" aria-label="Permalink to &quot;4.0.0-rc6&quot;">​</a></h2><p><em>2026-05-29</em></p><ul><li>arm64 .deb builds on Debian bookworm and declares its native runtime libraries (gRPC, protobuf, abseil, libplacebo, turbojpeg), fixing missing-shared-object and GLIBCXX-version failures on bookworm/Armbian SBCs (<a href="https://github.com/smazurov/videonode/commit/0e467ef" target="_blank" rel="noreferrer"><code>0e467ef</code></a>)</li></ul><h2 id="_4-0-0-rc5" tabindex="-1">4.0.0-rc5 <a class="header-anchor" href="#_4-0-0-rc5" aria-label="Permalink to &quot;4.0.0-rc5&quot;">​</a></h2><p><em>2026-05-28</em></p><ul><li>streams drop configurable publish targets: encoders publish to the built-in local RTSP relay, SRT/WebRTC fan out from there (breaking) (<a href="https://github.com/smazurov/videonode/commit/3ccdfaf" target="_blank" rel="noreferrer"><code>3ccdfaf</code></a>)</li><li>remove the in-app self-update service; updates ship via the .deb / APT repo only (breaking) (<a href="https://github.com/smazurov/videonode/commit/1de2fe0" target="_blank" rel="noreferrer"><code>1de2fe0</code></a>)</li><li>sources expose a liveness signal distinct from status, surfaced with per-entity log panels over the shared SSE stream (<a href="https://github.com/smazurov/videonode/commit/d5d9270" target="_blank" rel="noreferrer"><code>d5d9270</code></a>)</li><li>stream editing UI: partial-PATCH edits and auto-start preview that wakes an idle stream (<a href="https://github.com/smazurov/videonode/commit/4676230" target="_blank" rel="noreferrer"><code>4676230</code></a>)</li><li>pipeline fixes: compositor honors the NV12 UV-plane offset, source pins and reports the real capture rate via G_PARM (<a href="https://github.com/smazurov/videonode/commit/47767b1" target="_blank" rel="noreferrer"><code>47767b1</code></a>)</li><li>packaging cleanup: drop the legacy install.sh and the network-online unit dependency (<a href="https://github.com/smazurov/videonode/commit/321b127" target="_blank" rel="noreferrer"><code>321b127</code></a>)</li></ul><h2 id="_4-0-0-rc4" tabindex="-1">4.0.0-rc4 <a class="header-anchor" href="#_4-0-0-rc4" aria-label="Permalink to &quot;4.0.0-rc4&quot;">​</a></h2><p><em>2026-05-28</em></p><ul><li>packaging: enroll SUDO_USER on upgrade, not just first install (<a href="https://github.com/smazurov/videonode/commit/37f0656" target="_blank" rel="noreferrer"><code>37f0656</code></a>)</li></ul><h2 id="_4-0-0-rc3" tabindex="-1">4.0.0-rc3 <a class="header-anchor" href="#_4-0-0-rc3" aria-label="Permalink to &quot;4.0.0-rc3&quot;">​</a></h2><p><em>2026-05-27</em></p><ul><li>VitePress docs site with Mermaid, search, versioned navbar (<a href="https://github.com/smazurov/videonode/commit/cdd37c1" target="_blank" rel="noreferrer"><code>cdd37c1</code></a>)</li><li>release pipeline rewrite: matrix build replaces goreleaser, chglog-driven .deb (<a href="https://github.com/smazurov/videonode/commit/feff078" target="_blank" rel="noreferrer"><code>feff078</code></a>)</li><li>shadow-group-gated auth + postinst enrollment, service auto-start on install (<a href="https://github.com/smazurov/videonode/commit/f62e5a3" target="_blank" rel="noreferrer"><code>f62e5a3</code></a>)</li><li>composer UI: auto-slot on input add, canvas rotation moved to inspector (<a href="https://github.com/smazurov/videonode/commit/74749ac" target="_blank" rel="noreferrer"><code>74749ac</code></a>)</li><li>source reports placeholder dims while V4L2 inactive (<a href="https://github.com/smazurov/videonode/commit/16f5389" target="_blank" rel="noreferrer"><code>16f5389</code></a>)</li></ul><h2 id="_4-0-0-rc1" tabindex="-1">4.0.0-rc1 <a class="header-anchor" href="#_4-0-0-rc1" aria-label="Permalink to &quot;4.0.0-rc1&quot;">​</a></h2><p><em>2026-05-27</em></p><ul><li>feat(packaging): unified .deb via nfpm + GitHub Pages APT repo (<a href="https://github.com/smazurov/videonode/commit/c57d69e" target="_blank" rel="noreferrer"><code>c57d69e</code></a>)</li><li>refactor(packaging): replace CPack with nfpm (<a href="https://github.com/smazurov/videonode/commit/72c5d66" target="_blank" rel="noreferrer"><code>72c5d66</code></a>)</li></ul><h2 id="_3-1-0" tabindex="-1">3.1.0 <a class="header-anchor" href="#_3-1-0" aria-label="Permalink to &quot;3.1.0&quot;">​</a></h2><p><em>2026-05-18</em></p><ul><li>feat: v3.1.0 release (<a href="https://github.com/smazurov/videonode/commit/676bf30" target="_blank" rel="noreferrer"><code>676bf30</code></a>)</li></ul>',20)])])}const f=r(i,[["render",l]]);export{u as __pageData,f as default};
